pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount != 10);
        uint256 pay = bound(amount, 1, 1 ether);
        vm.deal(actor, pay);

        bool ok;
        vm.prank(actor);
        try c.play{value: pay}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
